function ExperiencePage({ online = false, onBack, currency, onCurrencyChange }) {
  const [currencyOpen, setCurrencyOpen] = useState(false)
  const [filter, setFilter] = useState('All')
  useEffect(() => { const closeCurrency = (event) => { if (!event.target.closest('.currency-wrap')) setCurrencyOpen(false) }; document.addEventListener('pointerdown', closeCurrency); return () => document.removeEventListener('pointerdown', closeCurrency) }, [])
  const categories = ['All', ...new Set(experienceCards.map((card) => card.category))]
  const cards = experienceCards.filter((card) => filter === 'All' || card.category === filter)
  return <main className="experience-page"><div className="experience-top"><button type="button" className="back-button" onClick={onBack}>← Back to stays</button><span className="brand"><span className="brand-mark">⌂</span><span>airbnb</span></span><div className="currency-wrap"><button type="button" className="footer-currency-button" onClick={() => setCurrencyOpen(!currencyOpen)}><GlobeIcon /> {currency[0]}</button>{currencyOpen && <CurrencyMenu onSelect={(item) => { onCurrencyChange(item); setCurrencyOpen(false) }} />}</div></div><section className="experience-hero"><p className="eyebrow">{online ? 'Connect from anywhere' : 'Go beyond the stay'}</p><h1>{online ? 'Online Experiences' : 'Experiences'}</h1><p>{online ? 'Meet inspiring people and discover new skills from your own home.' : 'Music, festivals, food, culture, and active days hosted by people who know their world by heart.'}</p></section><section className="experience-section"><div className="experience-heading"><div><span className="eyebrow">{cards.length} ways to go out</span><h2>{online ? 'Explore online with hosts around the world' : 'Find your next good night out'}</h2></div><div className="experience-filters" aria-label="Experience categories">{categories.map((category) => <button type="button" className={filter === category ? 'active' : ''} key={category} onClick={() => setFilter(category)}>{category}</button>)}</div></div><div className="experience-grid">{cards.map((card) => <article className="experience-card" key={card.title}><img src={card.image} alt={card.title} onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&w=900&q=85' }} /><div><span className="experience-pill">{online ? 'Online' : card.category}</span><h3>{online ? card.title.replace(' in ', ' with ') : card.title}</h3><p>{card.copy}</p><small>{online ? 'Online from anywhere' : card.location}</small><strong>From {formatMoney(card.price, currency)} / guest</strong><button type="button" onClick={() => alert(`${card.title} selected`)}>See details →</button></div></article>)}</div></section></main>
}

function LoginPage({ onLogin, onBack }) {
  const [mode, setMode] = useState('login')
  const [name, setName] = useState('')
  const [email, setEmail] = useState('workngilane@gmail.com')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [googleConfigured, setGoogleConfigured] = useState(false)
  const [appleConfigured, setAppleConfigured] = useState(false)
  const googleButton = useRef(null)
  const submit = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const endpoint = mode === 'login' ? '/api/auth/login' : '/api/auth/signup'; const response = await fetch(endpoint, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, email, password }) }); const data = await response.json(); if (!response.ok) return setError(data.error || 'Unable to continue'); onLogin(data.user) } catch { setError('The server is unavailable. Start it with npm run dev:full.') } finally { setBusy(false) } }
  useEffect(() => {
    let cancelled = false
    let renderTimer
    fetch('/api/auth/config').then((response) => response.json()).then((config) => { setGoogleConfigured(Boolean(config.googleClientId)); setAppleConfigured(Boolean(config.appleConfigured))
      const renderGoogle = () => { if (cancelled || !config.googleClientId || !window.google?.accounts?.id || !googleButton.current) return; window.google.accounts.id.initialize({ client_id: config.googleClientId, callback: async ({ credential }) => { setBusy(true); setError(''); const response = await fetch('/api/auth/google/token', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ credential }) }); const data = await response.json(); setBusy(false); if (!response.ok) return setError(data.error || 'Google login failed'); onLogin(data.user) } }); window.google.accounts.id.renderButton(googleButton.current, { theme: 'outline', size: 'large', width: 360, text: 'continue_with' }) }
      const waitForGoogle = () => { renderGoogle(); if (!cancelled && (!window.google?.accounts?.id || !googleButton.current)) renderTimer = window.setTimeout(waitForGoogle, 100) }
      waitForGoogle()
    })
    return () => { cancelled = true; window.clearTimeout(renderTimer) }
  }, [onLogin])
  return <main className="auth-page"><button className="back-button" type="button" onClick={onBack}>← Back to Airbnb</button><div className="auth-card"><div className="auth-brand"><span className="brand-mark">⌂</span><span>airbnb</span></div><h1>{mode === 'login' ? 'Log in' : 'Create account'}</h1><p className="auth-subtitle">{mode === 'login' ? 'Welcome back to Airbnb' : 'Join Airbnb and start exploring'}</p><form onSubmit={submit}>{mode === 'signup' && <label>Full name<input type="text" value={name} onChange={(event) => setName(event.target.value)} placeholder="Your full name" required /></label>}<label>Email<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} required /></label><label>Password<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} minLength="8" required /></label>{error && <p className="auth-error">{error}</p>}<button className="auth-submit" type="submit" disabled={busy}>{busy ? 'Please wait...' : mode === 'login' ? 'Log in' : 'Sign up'}</button></form>{mode === 'login' && <><div className="auth-divider"><span>or</span></div>{googleConfigured ? <div className="google-button" ref={googleButton}></div> : <button className="social-button" type="button" onClick={() => setError('Google login needs GOOGLE_CLIENT_ID configured in the server .env file.')}><strong>G</strong> Continue with Google</button>}{appleConfigured ? <button className="social-button" type="button" onClick={() => { window.location.href = '/api/auth/apple' }}><strong>●</strong> Continue with Apple</button> : <button className="social-button" type="button" onClick={() => setError('Apple login needs APPLE_CLIENT_ID, APPLE_TEAM_ID, APPLE_KEY_ID, and APPLE_PRIVATE_KEY configured in .env.')}><strong>●</strong> Continue with Apple</button>}</>}<button className="auth-switch" type="button" onClick={() => { setMode(mode === 'login' ? 'signup' : 'login'); setError(''); setPassword('') }}>{mode === 'login' ? 'New to Airbnb? Sign up' : 'Already have an account? Log in'}</button><p className="auth-note">Admin access is granted only to the authorized Workngilane account.</p></div></main>
}

function TrendChart({ data = [] }) {
  const max = Math.max(...data.map((item) => item.revenue), 1); const points = data.map((item, index) => `${(index / Math.max(data.length - 1, 1)) * 100},${100 - (item.revenue / max) * 80}`).join(' ')
  return <div className="trend-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Monthly revenue trend"><defs><linearGradient id="trend-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#ff385c" stopOpacity=".22" /><stop offset="1" stopColor="#ff385c" stopOpacity="0" /></linearGradient></defs><polyline points={`0,100 ${points} 100,100`} fill="url(#trend-fill)" stroke="none" /><polyline points={points} fill="none" stroke="#ff385c" strokeWidth="1.8" vectorEffect="non-scaling-stroke" /></svg><div className="chart-labels">{data.map((item) => <span key={item.month}>{item.month}</span>)}</div></div>
}

